import os, sys, pathlib, runpy
try:
    p = os.environ.get('CLAUDE_PROJECT_DIR', '')
    r = pathlib.Path(p) if (p and (pathlib.Path(p)/'scripts'/'hooks').is_dir()) else next((d for d in [pathlib.Path.cwd(), *pathlib.Path.cwd().parents] if (d/'scripts'/'hooks').is_dir()), None)
    if r:
        os.chdir(str(r))
        sys.path.insert(0, str(r / 'js-development'))
        f = r / 'scripts' / 'hooks' / sys.argv[1]
        if f.is_file():
            runpy.run_path(str(f), run_name='__main__')
except BaseException:
    pass
sys.exit(0)

